#!/usr/bin/env python3
"""Check: no line in a Markdown file is longer than 80 characters.

    line-length <directory>

Exit 0 when every line fits, 1 when one does not.
"""
import os
import sys

LIMIT = 80


def main(root):
    bad = []
    for d, dirs, files in os.walk(root):
        dirs[:] = sorted(x for x in dirs if x not in (".git", "formwork"))
        for f in sorted(files):
            if not f.endswith(".md"):
                continue
            path = os.path.join(d, f)
            with open(path, encoding="utf-8") as fh:
                for i, line in enumerate(fh, 1):
                    n = len(line.rstrip("\n"))
                    if n > LIMIT:
                        bad.append("%s:%d: %d characters, the limit is %d"
                                   % (os.path.relpath(path, root), i, n, LIMIT))
    for b in bad:
        print(b)
    if bad:
        print("line-length: %d line(s) too long" % len(bad))
        return 1
    print("line-length: every line fits")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1] if len(sys.argv) > 1 else "."))
